const rawUrl = String(tobub.params.url || '').trim();
const durationMinutes = tobub.params.durationMinutes !== undefined ? Number(tobub.params.durationMinutes) : null;
const legacyDurationMs = tobub.params.durationMs !== undefined ? Number(tobub.params.durationMs) : null;
const durationMs = legacyDurationMs !== null ? legacyDurationMs : (durationMinutes !== null ? durationMinutes * 60000 : 60000);
const initialWaitSeconds = Number(tobub.params.initialWaitSeconds ?? 10);
const pollIntervalSeconds = Number(tobub.params.pollIntervalSeconds ?? 2);
const maxEvents = Number(tobub.params.maxEvents ?? 200);
const minMessageLength = Number(tobub.params.minMessageLength ?? 1);
const deduplicate = tobub.params.deduplicate !== false;
const captureSecUid = tobub.params.captureSecUid === true;
let targetUrl;
try { targetUrl = new URL(rawUrl); } catch { throw new Error('params.url must be a valid URL.'); }
if (!['tiktok.com', 'www.tiktok.com', 'm.tiktok.com'].includes(targetUrl.hostname.toLowerCase())) throw new Error('Use an official TikTok LIVE URL.');
if (targetUrl.protocol !== 'http:' && targetUrl.protocol !== 'https:') throw new Error('LIVE URLs must use HTTP or HTTPS.');
const roomMatch = targetUrl.pathname.match(/^\/@([^/]+)\/live\/?$/i);
if (!roomMatch) throw new Error('Use a LIVE URL in this format: https://www.tiktok.com/@username/live.');
if (!Number.isInteger(durationMs) || durationMs < 1000 || durationMs > 600000) throw new Error('Capture duration must be 1 to 10 minutes. The legacy durationMs parameter accepts 1,000 to 600,000 milliseconds.');
if (!Number.isInteger(initialWaitSeconds) || initialWaitSeconds < 1 || initialWaitSeconds > 30) throw new Error('initialWaitSeconds must be from 1 to 30 seconds.');
if (!Number.isInteger(pollIntervalSeconds) || pollIntervalSeconds < 1 || pollIntervalSeconds > 15) throw new Error('pollIntervalSeconds must be from 1 to 15 seconds.');
if (!Number.isInteger(maxEvents) || maxEvents < 1 || maxEvents > 1000) throw new Error('maxEvents must be an integer from 1 to 1000.');
if (!Number.isInteger(minMessageLength) || minMessageLength < 0 || minMessageLength > 1000) throw new Error('minMessageLength must be an integer from 0 to 1000.');

const url = targetUrl.toString();
let roomId;
try { roomId = decodeURIComponent(roomMatch[1]); } catch { throw new Error('Invalid encoding in the LIVE username.'); }
if (!/^[A-Za-z0-9._]{1,64}$/.test(roomId)) throw new Error('Invalid username in the LIVE URL.');
const startedAt = new Date().toISOString();
const executionRunId = typeof tobub.execution?.runId === 'string' && tobub.execution.runId.trim() ? tobub.execution.runId.trim() : startedAt;
const page = await tobub.browser.open({ url });
let collection;
let collectionClosed = false;
let metadataSaved;
let eventCount = 0;
let duplicateCount = 0;
let filteredCount = 0;
let droppedCount = 0;
const seenKeys = new Set();
const pendingRecords = [];

const flush = async () => {
  if (pendingRecords.length) await collection.append(pendingRecords.splice(0));
};
const readChatRows = async () => {
  const expression = String.raw`(()=>Array.from(document.querySelectorAll("[data-e2e=\"chat-message\"]")).slice(-150).map((el,index)=>{const name=el.querySelector("[data-e2e=\"message-owner-name\"]");return{username:String((name&&name.innerText)||"").trim(),rawText:String(el.innerText||"").trim(),messageId:String(el.getAttribute("data-message-id")||el.getAttribute("data-id")||el.id||""),domIndex:index}}))()`;
  const result = await tobub.atoms.evaluate({ mode: 'expression', expression }, { page });
  const value = result && result.value !== undefined ? result.value : (result && result.result !== undefined ? result.result : result);
  return Array.isArray(value) ? value : [];
};
const parseMessage = (row) => {
  const username = String(row.username || '').replace(/\s+/g, ' ').trim();
  const lines = String(row.rawText || '').split(/\r?\n/).map(line => line.trim()).filter(Boolean);
  const messageLines = username && lines[0] === username ? lines.slice(1) : lines.filter(line => line !== username);
  return { username, message: messageLines.join(' ').trim() };
};
try {
  collection = await tobub.data.open({
    name: 'tiktok-live-room-events',
    policy: { maxRecords: maxEvents, batchSize: 100, flushIntervalMs: 5000 },
    metadata: {
      schemaVersion: 1,
      recordType: 'live_comment',
      roomId,
      url,
      startedAt,
      executionRunId,
      storageMode: 'metadata_file',
      durationMs,
      durationMinutes: durationMs / 60000,
      initialWaitSeconds,
      pollIntervalSeconds,
      minMessageLength,
      deduplicate,
      captureSecUid,
      source: 'tiktok-live-chat-dom'
    }
  });
  metadataSaved = await tobub.db.saveContent({
    platform: 'tiktok',
    contentType: 'live_room_monitor',
    externalId: roomId + ':' + collection.id + ':metadata',
    title: 'TikTok LIVE monitoring: ' + roomId,
    summary: 'TikTok LIVE chat DOM capture',
    url,
    rawData: { roomId, url, startedAt, executionRunId, durationMs, maxEvents, minMessageLength, deduplicate, captureSecUid, source: 'tiktok-live-chat-dom' },
    metadata: {
      tobub_data: { collection_id: collection.id, role: 'detail', mode: 'event', format: 'jsonl', schema_version: 1 },
      roomId,
      startedAt,
      durationMs,
      durationMinutes: durationMs / 60000,
      initialWaitSeconds,
      pollIntervalSeconds,
      minMessageLength,
      deduplicate,
      source: 'tiktok-live-chat-dom'
    },
    tags: ['tiktok', 'live', 'monitor', 'chat', 'dom'],
    observationSource: 'live_room_monitor',
    observationMeta: { roomId, collectionId: collection.id, role: 'detail', mode: 'event', format: 'jsonl', schemaVersion: 1, source: 'tiktok-live-chat-dom' }
  });

  await tobub.atoms.waitFor({ delay: initialWaitSeconds * 1000 }, { page });
  const initialRows = await readChatRows();
  const processRows = async (rows, capturedAt) => {
    const occurrences = new Map();
    for (const row of rows) {
      if (eventCount >= maxEvents) { droppedCount++; continue; }
      const parsed = parseMessage(row);
      if (!parsed.username || !parsed.message) continue;
      const signature = parsed.username + '\\u0000' + parsed.message;
      const occurrence = (occurrences.get(signature) || 0) + 1;
      occurrences.set(signature, occurrence);
      const messageId = row.messageId || '';
      const rowKey = messageId ? 'id:' + messageId : (deduplicate ? signature : signature + '\\u0000' + occurrence);
      if (occurrences.get('row:' + rowKey)) { duplicateCount++; continue; }
      occurrences.set('row:' + rowKey, 1);
      if (seenKeys.has(rowKey)) continue;
      seenKeys.add(rowKey);
      if (Array.from(parsed.message).length < minMessageLength) { filteredCount++; continue; }
      const record = {
        type: 'live_comment',
        payload: {
          roomId,
          user: { name: parsed.username, avatar: null, id: null, gradeLevel: null, gradeIcon: null, isFansClubMember: false, fansClubBadge: null, secUid: null },
          message: parsed.message,
          capturedAt,
          sequence: eventCount + 1,
          source: 'dom_live_chat',
          messageId
        },
        meta: { roomId, source: 'dom_live_chat', capturedAt }
      };
      pendingRecords.push(record);
      eventCount++;
    }
    await flush();
  };
  await processRows(initialRows, new Date().toISOString());
  const deadline = Date.now() + durationMs;
  const monitor = tobub.monitor.start(async ({ signal, stop }) => {
    if (signal?.aborted || Date.now() >= deadline || eventCount >= maxEvents) { stop(); return; }
    const rows = await readChatRows();
    await processRows(rows, new Date().toISOString());
    if (Date.now() >= deadline || eventCount >= maxEvents) stop();
  }, { intervalMs: pollIntervalSeconds * 1000, immediate: true, schedule: 'fixed-delay' });
  await monitor.wait();

  await flush();
  const dataResult = await collection.close();
  collectionClosed = true;
  const warning = eventCount === 0
    ? 'No chat messages were read from the LIVE page. The room may have ended, chat may be unavailable, or the page may still be loading.'
    : (captureSecUid ? 'The current TikTok chat page does not expose secUid. Only display names and visible messages are captured.' : '');
  return {
    url,
    roomId,
    durationMinutes: durationMs / 60000,
    pollIntervalSeconds,
    startedAt,
    endedAt: new Date().toISOString(),
    eventCount,
    storage: {
      metadataContentItemId: metadataSaved && Number.isFinite(Number(metadataSaved.contentItemId)) ? Number(metadataSaved.contentItemId) : null,
      metadataObservationId: metadataSaved && Number.isFinite(Number(metadataSaved.observationId)) ? Number(metadataSaved.observationId) : null,
      dataCollectionId: dataResult.id,
      detailFile: dataResult.outputs && dataResult.outputs[0] ? dataResult.outputs[0].relativePath : null
    },
    stats: {
      duplicates: duplicateCount,
      secUidResolved: 0,
      decoderErrors: 0,
      delivered: eventCount,
      filtered: filteredCount,
      dropped: droppedCount
    },
    warning
  };
} finally {
  if (collection && pendingRecords.length) await flush().catch(() => undefined);
  if (collection && !collectionClosed) await collection.close().catch(() => undefined);
  await tobub.browser.close(page).catch(() => undefined);
}
